 p_id=>wwv_flow_imp.id(22102809872070234)
,p_plug_name=>'ALUMNOS'
,p_static_id=>'alumnos'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT a.n_control,',
'       a.nombre,',
'       a.apellidos,',
'       a.curp,',
'       a.fecha_nacimiento,',
'       TRUNC(MONTHS_BETWEEN(SYSDATE, a.fecha_nacimiento)/12) AS edad,',
'       DECODE(a.sexo, ''H'', ''Hombre'', ''M'', ''Mujer'', ''X'', ''No binario'') AS sexo,',
'       e.nombre AS estado_nacimiento,',
'       a.direccion,',
'       m.nombre AS municipio,',
'       c.nombre AS ciclo,',
'       a.anio_ingreso,',
'       a.mail,',
'       a.telefono,',
'       a.activo,',
'       a.creditos',
'FROM alumnos a',
'LEFT JOIN municipios m ON m.id_municipio = a.id_municipio',
'LEFT JOIN ciclos c ON c.id_ciclo = a.id_ciclo',
'LEFT JOIN estados e ON e.id_estado = a.id_estado_nacimiento'))
,p_plug_source_type=>'NATIVE_IR'
