,p_plug_name=>'resumen'
,p_static_id=>'resumen'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_prom NUMBER;',
'  l_cred NUMBER;',
'  l_nombre VARCHAR2(200);',
'BEGIN',
'  SELECT nombre || '' '' || apellidos, creditos',
'    INTO l_nombre, l_cred',
'    FROM alumnos WHERE n_control = :P30_N_CONTROL;',
'',
'  SELECT ROUND(AVG(calificacion), 2)',
'    INTO l_prom',
'    FROM calificaciones WHERE n_control = :P30_N_CONTROL AND calificacion IS NOT NULL;',
'',
'  RETURN ''<h3>'' || apex_escape.html(l_nombre) || ''</h3>''',
'      || ''<p><b>No. de control:</b> '' || apex_escape.html(:P30_N_CONTROL) || ''<br>''',
unistr('      || ''<b>Cr\00E9ditos acumulados:</b> '' || l_cred || ''<br>'''),
'      || ''<b>Promedio general:</b> '' || NVL(TO_CHAR(l_prom), ''N/A'') || ''</p>'';',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P30_N_CONTROL'
,p_plug_display_condition_type=>'ITEM_IS_NOT_NULL'
